#chatgpt-go-watchdog {
  position: fixed;
  z-index: 2147483647;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: stretch;
  width: 58px;
  padding: 6px;
  border-radius: 12px;
  background: rgba(18,18,18,.92);
  box-shadow: 0 8px 30px rgba(0,0,0,.35);
  user-select: none;
  font: 11px/1.15 system-ui, -apple-system, Segoe UI, sans-serif;
  backdrop-filter: blur(10px);
}
#chatgpt-go-watchdog button {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 8px;
  padding: 7px 3px;
  background: #242424;
  color: #fff;
  cursor: pointer;
  font-weight: 700;
}
#chatgpt-go-watchdog button:hover { background: #303030; }
#chatgpt-go-watchdog .cg-update-notice {
  position: absolute;
  left: 8px;
  bottom: calc(100% + 8px);
  min-width: 268px;
  max-width: min(430px, calc(100vw - 32px));
  display: none;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 12px;
  box-sizing: border-box;
  border: 1px solid rgba(244,166,76,.72);
  border-radius: 11px;
  background: rgba(38,31,23,.97);
  color: rgba(255,248,238,.97);
  box-shadow: 0 8px 30px rgba(0,0,0,.38), 0 0 22px rgba(244,154,56,.23);
  pointer-events: auto;
  z-index: 4;
}
#chatgpt-go-watchdog[data-version-notice="show"] .cg-update-notice {
  display: flex;
  animation: cg-version-notice-pop .24s ease-out, cg-version-notice-glow 1.6s ease-in-out 2;
}
#chatgpt-go-watchdog[data-version-notice="show"] .cg-version {
  border-color: rgba(244,166,76,.78) !important;
  box-shadow: 0 0 12px rgba(244,154,56,.32) !important;
  color: rgba(255,238,211,.98) !important;
}
#chatgpt-go-watchdog .cg-update-copy {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    "kicker version"
    "time time";
  align-items: center;
  gap: 3px 7px;
  min-width: 0;
  flex: 1 1 auto;
}
#chatgpt-go-watchdog .cg-update-kicker {
  grid-area: kicker;
  font-size: 8px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: .08em;
  color: rgba(255,187,105,.95);
}
#chatgpt-go-watchdog .cg-update-version {
  grid-area: version;
  min-width: 0;
  font-size: 12px;
  line-height: 1.1;
  font-weight: 800;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#chatgpt-go-watchdog .cg-update-time {
  grid-area: time;
  font-size: 9px;
  line-height: 1.2;
  color: rgba(232,221,205,.76);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#chatgpt-go-watchdog .cg-update-dismiss {
  width: 38px !important;
  min-width: 38px !important;
  height: 27px !important;
  flex: 0 0 38px !important;
  padding: 0 !important;
  border-color: rgba(244,166,76,.42) !important;
  background: rgba(244,154,56,.16) !important;
  color: rgba(255,239,217,.94) !important;
  font-size: 9px !important;
}
@keyframes cg-version-notice-pop {
  from { opacity: 0; transform: translateY(5px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes cg-version-notice-glow {
  0%,100% { box-shadow: 0 8px 30px rgba(0,0,0,.38), 0 0 16px rgba(244,154,56,.18); }
  50% { box-shadow: 0 8px 30px rgba(0,0,0,.38), 0 0 28px rgba(244,154,56,.34); }
}
#chatgpt-go-watchdog .cg-auto.on {
  outline: 2px solid rgba(255,255,255,.55);
  background: #3a3a3a;
}
#chatgpt-go-watchdog .cg-status {
  color: #cfcfcf;
  padding: 2px 1px 0;
  white-space: nowrap;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 9px;
  line-height: 1.15;
}
#chatgpt-go-watchdog .cg-status:empty {
  display: none;
}

/* v4.42.41 composer-aligned dock. GO is intentionally rightmost, roughly under ChatGPT Send. */
#chatgpt-go-watchdog {
  position: fixed !important;
  left: 24px !important;
  right: 24px !important;
  bottom: 0 !important;
  top: auto !important;
  width: auto !important;
  height: 34px !important;
  box-sizing: border-box;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start;
  gap: 5px !important;
  padding: 3px 4px !important;
  border-radius: 0 !important;
  border: 0 !important;
  border-top: 1px solid rgba(128,178,214,.24) !important;
  background: rgba(18,20,23,.93) !important;
  box-shadow: 0 -1px 8px rgba(82,151,205,.15) !important;
  backdrop-filter: blur(8px) saturate(.95);
  pointer-events: none;
}
#chatgpt-go-watchdog::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: -2px;
  height: 2px;
  background: linear-gradient(90deg, rgba(91,145,181,.12), rgba(96,164,214,.58) 34%, rgba(116,180,220,.66) 50%, rgba(96,164,214,.58) 66%, rgba(91,145,181,.12));
  box-shadow: 0 -1px 8px rgba(86,157,211,.28), 0 1px 6px rgba(86,157,211,.18);
  pointer-events: none;
}
#chatgpt-go-watchdog::before {
  content: attr(data-meta);
  order: 0;
  flex: 0 1 150px;
  min-width: 78px;
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(226,229,232,.76);
  font-size: 9px;
  letter-spacing: .01em;
  padding-left: 2px;
}
#chatgpt-go-watchdog .cg-status {
  order: 1;
  flex: 1 1 auto;
  min-width: 0;
  padding: 0 7px !important;
  text-align: right !important;
  color: rgba(226,229,232,.72) !important;
  font-size: 9px !important;
  line-height: 1 !important;
  pointer-events: none;
}
#chatgpt-go-watchdog button {
  pointer-events: auto;
  flex: 0 0 60px;
  width: 60px !important;
  height: 27px;
  padding: 0 8px !important;
  border-radius: 8px !important;
  border: 1px solid rgba(255,255,255,.18) !important;
  background: rgba(255,255,255,.10) !important;
  color: rgba(247,248,249,.90) !important;
  box-shadow: none !important;
  font-size: 9px;
  line-height: 1;
}
#chatgpt-go-watchdog button:hover {
  filter: brightness(1.18);
  color: #fff !important;
}
#chatgpt-go-watchdog .cg-auto {
  order: 2;
  background: rgba(72,112,79,.42) !important;
  border-color: rgba(111,151,117,.46) !important;
}
#chatgpt-go-watchdog .cg-auto.on {
  outline: none !important;
  background: rgba(72,126,82,.62) !important;
  border-color: rgba(127,174,134,.68) !important;
  color: rgba(250,255,250,.96) !important;
}
#chatgpt-go-watchdog .cg-new {
  order: 3;
  background: rgba(145,103,54,.48) !important;
  border-color: rgba(181,134,75,.52) !important;
}
#chatgpt-go-watchdog .cg-stop {
  order: 4;
  background: rgba(132,69,74,.48) !important;
  border-color: rgba(170,94,100,.54) !important;
}
#chatgpt-go-watchdog .cg-go {
  order: 5;
  flex-basis: 66px;
  width: 66px !important;
  background: rgba(60,105,146,.56) !important;
  border-color: rgba(99,148,187,.62) !important;
  color: rgba(250,253,255,.96) !important;
}
@media (max-width: 430px) {
  #chatgpt-go-watchdog { gap: 4px !important; padding-inline: 2px !important; }
  #chatgpt-go-watchdog::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: -2px;
  height: 2px;
  background: linear-gradient(90deg, rgba(91,145,181,.12), rgba(96,164,214,.58) 34%, rgba(116,180,220,.66) 50%, rgba(96,164,214,.58) 66%, rgba(91,145,181,.12));
  box-shadow: 0 -1px 8px rgba(86,157,211,.28), 0 1px 6px rgba(86,157,211,.18);
  pointer-events: none;
}
#chatgpt-go-watchdog::before { flex-basis: 82px; min-width: 68px; max-width: 82px; font-size: 8px; }
  #chatgpt-go-watchdog .cg-status { font-size: 8px !important; padding-inline: 2px !important; }
  #chatgpt-go-watchdog button { flex-basis: 48px; width: 48px !important; padding-inline: 4px !important; font-size: 8px; }
  #chatgpt-go-watchdog .cg-go { flex-basis: 54px; width: 54px !important; }
}

/* v4.42.42: grid dock. Version left, passive status centered, controls pinned to the right with GO nearest Send. */
#chatgpt-go-watchdog {
  display: grid !important;
  grid-template-columns: minmax(128px, 1fr) minmax(110px, 1fr) 60px 60px 60px 70px;
  column-gap: 6px !important;
  align-items: center !important;
  height: 36px !important;
  bottom: 3px !important;
  padding: 4px 6px !important;
  border-radius: 12px !important;
  border: 1px solid rgba(255,255,255,.10) !important;
  border-top-color: rgba(126,183,221,.30) !important;
  background: rgba(22,24,27,.96) !important;
  box-shadow: 0 2px 12px rgba(0,0,0,.24), 0 -1px 7px rgba(88,158,207,.14) !important;
}
#chatgpt-go-watchdog::after {
  left: 12px !important;
  right: 12px !important;
  top: -2px !important;
  height: 2px !important;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(89,146,185,.10), rgba(91,168,220,.56) 30%, rgba(126,194,235,.72) 50%, rgba(91,168,220,.56) 70%, rgba(89,146,185,.10)) !important;
  box-shadow: 0 -1px 7px rgba(91,168,220,.27), 0 1px 5px rgba(91,168,220,.18) !important;
}
#chatgpt-go-watchdog::before {
  grid-column: 1;
  order: initial !important;
  justify-self: start;
  align-self: center;
  width: auto;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 5px 9px !important;
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 8px;
  background: rgba(255,255,255,.055);
  color: rgba(235,238,241,.82) !important;
  font-size: 9px !important;
  line-height: 1;
}
#chatgpt-go-watchdog .cg-status {
  display: flex !important;
  grid-column: 2;
  order: initial !important;
  justify-self: center;
  align-items: center;
  justify-content: center;
  width: min(100%, 210px);
  height: 23px;
  box-sizing: border-box;
  padding: 0 10px !important;
  border: 1px solid rgba(126,155,177,.16);
  border-radius: 999px;
  background: rgba(104,128,146,.11);
  color: rgba(229,235,239,.84) !important;
  font-size: 9px !important;
  font-weight: 650;
  letter-spacing: .035em;
  text-transform: uppercase;
  text-align: center !important;
  pointer-events: none;
}
#chatgpt-go-watchdog .cg-status::before {
  content: '';
  flex: 0 0 5px;
  width: 5px;
  height: 5px;
  margin-right: 6px;
  border-radius: 50%;
  background: rgba(113,176,216,.78);
  box-shadow: 0 0 5px rgba(113,176,216,.30);
}
#chatgpt-go-watchdog .cg-auto { grid-column: 3; }
#chatgpt-go-watchdog .cg-new  { grid-column: 4; }
#chatgpt-go-watchdog .cg-stop { grid-column: 5; }
#chatgpt-go-watchdog .cg-go   { grid-column: 6; }
#chatgpt-go-watchdog button {
  order: initial !important;
  width: 100% !important;
  min-width: 0 !important;
  height: 27px !important;
  padding: 0 8px !important;
  font-size: 9px !important;
}
#chatgpt-go-watchdog .cg-go {
  width: 100% !important;
  background: rgba(60,112,157,.62) !important;
  border-color: rgba(105,160,203,.70) !important;
}
#chatgpt-go-watchdog .cg-auto {
  background: rgba(74,122,82,.46) !important;
  border-color: rgba(117,161,123,.50) !important;
}
#chatgpt-go-watchdog .cg-auto.on { background: rgba(75,138,88,.68) !important; }
#chatgpt-go-watchdog .cg-new {
  background: rgba(151,108,56,.52) !important;
  border-color: rgba(188,142,81,.58) !important;
}
#chatgpt-go-watchdog .cg-stop {
  background: rgba(139,72,78,.52) !important;
  border-color: rgba(179,98,105,.60) !important;
}
@media (max-width: 620px) {
  #chatgpt-go-watchdog {
    grid-template-columns: minmax(92px, 1fr) minmax(72px, 1fr) 54px 54px 54px 60px;
    column-gap: 4px !important;
  }
  #chatgpt-go-watchdog::before { padding-inline: 7px !important; font-size: 8px !important; }
  #chatgpt-go-watchdog .cg-status { font-size: 8px !important; padding-inline: 6px !important; }
}
@media (max-width: 430px) {
  #chatgpt-go-watchdog {
    grid-template-columns: minmax(64px, .85fr) minmax(48px, 1fr) 39px 39px 39px 45px;
    column-gap: 3px !important;
    padding-inline: 4px !important;
  }
  #chatgpt-go-watchdog::before { padding-inline: 5px !important; font-size: 7.5px !important; }
  #chatgpt-go-watchdog .cg-status { font-size: 7.5px !important; padding-inline: 4px !important; }
  #chatgpt-go-watchdog button { padding-inline: 2px !important; font-size: 8px !important; }
}

/* v4.42.43: three independent dock zones. Meta left, passive status center, controls right. */
#chatgpt-go-watchdog {
  display: grid !important;
  grid-template-columns: minmax(112px, max-content) minmax(72px, 1fr) max-content !important;
  column-gap: 8px !important;
  align-items: center !important;
  height: 33px !important;
  bottom: 3px !important;
  padding: 2px 7px !important;
  border-radius: 13px !important;
  overflow: visible;
}
#chatgpt-go-watchdog::before { content: none !important; display: none !important; }
#chatgpt-go-watchdog .cg-meta {
  grid-column: 1;
  justify-self: start;
  min-width: 0;
  max-width: 190px;
  box-sizing: border-box;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 6px 10px;
  border-radius: 9px;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.07);
  color: rgba(238,241,244,.84);
  font-size: 9px;
  line-height: 1;
  pointer-events: none;
}
#chatgpt-go-watchdog .cg-status {
  grid-column: 2 !important;
  justify-self: center !important;
  width: min(100%, 188px) !important;
  height: 21px !important;
  box-sizing: border-box;
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 10px !important;
  border-radius: 999px !important;
  border: 1px solid rgba(130,153,171,.20) !important;
  background: rgba(103,127,145,.12) !important;
  color: rgba(233,238,242,.86) !important;
  font-size: 9px !important;
  font-weight: 650;
  letter-spacing: .035em;
  text-transform: uppercase;
  text-align: center !important;
  pointer-events: none !important;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#chatgpt-go-watchdog .cg-status::before {
  content: '';
  flex: 0 0 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(145,166,181,.82);
  box-shadow: 0 0 6px rgba(145,166,181,.24);
}
#chatgpt-go-watchdog[data-status-tone="active"] .cg-status::before { background: rgba(110,190,124,.92); box-shadow: 0 0 7px rgba(110,190,124,.34); }
#chatgpt-go-watchdog[data-status-tone="amber"] .cg-status::before { background: rgba(218,161,84,.92); box-shadow: 0 0 7px rgba(218,161,84,.32); }
#chatgpt-go-watchdog[data-status-tone="danger"] .cg-status::before { background: rgba(211,104,111,.92); box-shadow: 0 0 7px rgba(211,104,111,.34); }
#chatgpt-go-watchdog .cg-timer {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 104px;
  width: 104px;
  height: 25px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 1px solid rgba(218,161,84,.34);
  background: rgba(218,161,84,.10);
  color: rgba(255,220,169,.92);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .04em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: inset 0 0 7px rgba(218,161,84,.04);
}
#chatgpt-go-watchdog .cg-timer[data-mode="countdown"] {
  border-color: rgba(225,170,91,.62);
  background: rgba(218,161,84,.16);
  color: rgba(255,230,190,.98);
  box-shadow: 0 0 8px rgba(218,161,84,.18), inset 0 0 7px rgba(218,161,84,.06);
}
#chatgpt-go-watchdog .cg-timer[data-mode="error"] {
  border-color: rgba(211,104,111,.74);
  background: rgba(211,104,111,.15);
  color: rgba(255,215,218,.98);
  box-shadow: 0 0 9px rgba(211,104,111,.22);
}
#chatgpt-go-watchdog .cg-timer[data-mode="idle"] {
  border-color: rgba(145,166,181,.20);
  background: rgba(145,166,181,.06);
  color: rgba(214,220,225,.52);
}
#chatgpt-go-watchdog .cg-actions {
  grid-column: 3;
  justify-self: end;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  min-width: 0;
  pointer-events: auto;
}
#chatgpt-go-watchdog .cg-actions button {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  flex: 0 0 58px !important;
  width: 58px !important;
  height: 25px !important;
  margin: 0 !important;
  padding: 0 8px !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: static !important;
  grid-column: auto !important;
  order: initial !important;
}
#chatgpt-go-watchdog .cg-actions .cg-go {
  flex-basis: 70px !important;
  width: 70px !important;
  margin-right: 1px !important;
}
@media (max-width: 620px) {
  #chatgpt-go-watchdog { grid-template-columns: minmax(88px, 1fr) minmax(58px, 1fr) max-content !important; column-gap: 5px !important; }
  #chatgpt-go-watchdog .cg-meta { max-width: 120px; padding-inline: 7px; font-size: 8px; }
  #chatgpt-go-watchdog .cg-status { width: min(100%, 138px) !important; padding-inline: 6px !important; font-size: 8px !important; }
  #chatgpt-go-watchdog .cg-actions { gap: 4px; }
  #chatgpt-go-watchdog .cg-actions button { flex-basis: 47px !important; width: 47px !important; padding-inline: 4px !important; font-size: 8px !important; }
  #chatgpt-go-watchdog .cg-actions .cg-go { flex-basis: 56px !important; width: 56px !important; }
}
@media (max-width: 430px) {
  #chatgpt-go-watchdog { grid-template-columns: 72px minmax(42px, 1fr) max-content !important; column-gap: 4px !important; padding-inline: 5px !important; }
  #chatgpt-go-watchdog .cg-meta { max-width: 72px; padding-inline: 5px; font-size: 7.5px; }
  #chatgpt-go-watchdog .cg-status { width: 100% !important; padding-inline: 4px !important; font-size: 7.5px !important; }
  #chatgpt-go-watchdog .cg-actions { gap: 3px; }
  #chatgpt-go-watchdog .cg-actions button { flex-basis: 36px !important; width: 36px !important; padding-inline: 2px !important; font-size: 7.5px !important; }
  #chatgpt-go-watchdog .cg-actions .cg-go { flex-basis: 44px !important; width: 44px !important; }
}

/* v4.42.45: split identity chips + neutral status fill with state-colored neon perimeter. */
#chatgpt-go-watchdog .cg-meta { display: none !important; }
#chatgpt-go-watchdog .cg-identity {
  grid-column: 1;
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  pointer-events: none;
}
#chatgpt-go-watchdog .cg-version,
#chatgpt-go-watchdog .cg-project {
  display: inline-flex;
  align-items: center;
  height: 21px;
  box-sizing: border-box;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.105);
  background: rgba(255,255,255,.05);
  color: rgba(232,235,238,.76);
  font-size: 8.5px;
  line-height: 1;
  white-space: nowrap;
}
#chatgpt-go-watchdog .cg-version { background: rgba(101,126,145,.09); border-color: rgba(132,157,176,.15); }
#chatgpt-go-watchdog .cg-project { background: rgba(128,106,151,.095); border-color: rgba(156,132,180,.18); color: rgba(239,232,245,.82); }
#chatgpt-go-watchdog .cg-status {
  background: rgba(30,34,38,.74) !important;
  border: 1px solid rgba(126,151,171,.34) !important;
  box-shadow: 0 0 7px rgba(112,153,181,.16), inset 0 0 7px rgba(112,153,181,.035) !important;
  color: rgba(238,241,243,.90) !important;
}
#chatgpt-go-watchdog .cg-status::before { display: none !important; content: none !important; }
#chatgpt-go-watchdog[data-status-tone="idle"] .cg-status {
  border-color: rgba(139,164,182,.38) !important;
  box-shadow: -11px 0 13px -9px rgba(125,158,181,.22), 11px 0 13px -9px rgba(125,158,181,.22), 0 0 6px rgba(125,158,181,.15), inset 0 0 6px rgba(125,158,181,.035) !important;
}
#chatgpt-go-watchdog[data-status-tone="active"] .cg-status {
  border-color: rgba(103,191,120,.62) !important;
  box-shadow: -13px 0 15px -9px rgba(90,193,111,.42), 13px 0 15px -9px rgba(90,193,111,.42), 0 0 7px rgba(90,193,111,.28), inset 0 0 7px rgba(90,193,111,.055) !important;
}
